{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.zouk_FACEBOOK_CONSOLIDATED_Intermediate AS SELECT Adset_Name, Adset_ID, FB.ad_id, FB.ad_name, \'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' AS Account_Name, Account_ID, Campaign_Name, Campaign_ID, CAST(Fb.date_start AS DATE) AS Date, SUM(CLICKS) AS Clicks, SUM(IFNULL(inline_link_clicks,0)) AS Link_Clicks, SUM(SPEND) AS Spend, SUM(IMPRESSIONS) AS Impressions, SUM(IFNULL(Fc.Conversions,0)) AS Conversions, SUM(IFNULL(Fc1.Conversions_1D_Click,0)) AS Meta_1D_Conversions, SUM(IFNULL(reach,0)) AS reach, SUM(IFNULL(frequency,0)) AS frequency, SUM(IFNULL(Fcv.Conversion_Value,0)) AS Conversion_Value, SUM(IFNULL(Fcv1.Conversion_Value_1D_Click,0)) AS Meta_1D_Conversions_Value, SUM(IFNULL(fd.add_to_carts,0)) AS Add_to_carts, SUM(IFNULL(fdv.add_to_cart_value,0)) AS Add_to_cart_value, SUM(IFNULL(Fp.purchase, 0)) AS Purchase, SUM(IFNULL(Fv.video_views, 0)) AS Video_Views, SUM(IFNULL(Fcm.Comment, 0)) AS Comment, SUM(IFNULL(Frc.post_reaction,0)) AS Post_Reaction, SUM(IFNULL(Feg.page_engagement,0)) AS Page_Engagement, SUM(IFNULL(Fl.Facebook_Like, 0)) AS Facebook_Like, SUM(IFNULL(fe.landing_page_views,0)) AS Landing_page_views, SUM(IFNULL(ff.initiate_checkouts,0)) AS Initiate_checkouts, SUM(IFNULL(ffv.initiate_checkouts_value,0)) AS Initiate_checkouts_value, \'Facebook\' AS Channel, \'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' AS Account FROM ( SELECT * FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data WHERE NOT(IFNULL(CONCAT(CAST(date_start AS DATE), ad_id), \'\') IN ( SELECT DISTINCT CONCAT(CAST(date_start AS DATE), ad_id) FROM `MapleMonk.zouk_db_product_customcampaigns_data` WHERE LOWER(IFNULL(ad_name, \'\')) LIKE \'%catalogue%\' )) ) FB LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') AS FLOAT64),0) + IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') AS FLOAT64),0)) Conversions FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start ) Fc ON Fb.ad_id = Fc.ad_id AND Fb.date_start = Fc.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.1d_click\') AS FLOAT64),0)) Conversions_1D_Click FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') IN (\'purchase\', \'offsite_conversion.fb_pixel_purchase\') GROUP BY ad_id, ad_name, date_start ) Fc1 ON Fb.ad_id = Fc1.ad_id AND Fb.date_start = Fc1.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') AS FLOAT64),0) + IFNULL(CAST(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') AS FLOAT64),0)) Conversion_Value FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start ) Fcv ON Fb.ad_id = Fcv.ad_id AND Fb.date_start = Fcv.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(CV,\'$.1d_click\') AS FLOAT64),0)) Conversion_Value_1D_Click FROM `maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data` LEFT JOIN UNNEST(ACTION_VALUES) AS CV WHERE JSON_EXTRACT_SCALAR(CV,\'$.action_type\') IN (\'omni_purchase\') GROUP BY ad_id, ad_name, date_start ) Fcv1 ON Fb.ad_id = Fcv1.ad_id AND Fb.date_start = Fcv1.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64),0)) purchase FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'purchase\' GROUP BY ad_id, ad_name, date_start ) Fp ON Fb.ad_id = Fp.ad_id AND Fb.date_start = Fp.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) AS Facebook_Like FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'like\' GROUP BY ad_id, ad_name, date_start ) Fl ON Fb.ad_id = Fl.ad_id AND Fb.date_start = Fl.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) AS comment FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` LEFT JOIN UNNEST (ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'comment\' GROUP BY ad_id, ad_name, date_start ) Fcm ON Fb.ad_id = Fcm.ad_id AND Fb.date_start = Fcm.date_start LEFT JOIN ( SELECT ad_ID, ad_name, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Page_Engagement FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` LEFT JOIN UNNEST (ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'page_engagement\' GROUP BY ad_id, ad_name, date_start ) Feg ON Fb.ad_id = Feg.ad_id AND Fb.date_start = Feg.date_start LEFT JOIN ( SELECT ad_ID, ad_name, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Post_Reaction FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` LEFT JOIN UNNEST (ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'post_reaction\' GROUP BY ad_id, ad_name, date_start ) Frc ON Fb.ad_id = Frc.ad_id AND Fb.date_start = Frc.date_start LEFT JOIN ( SELECT ad_id, Ad_name, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) video_views FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'video_view\' GROUP BY ad_id, Ad_name, date_start ) Fv ON Fb.ad_id = Fv.ad_id AND Fb.date_start = Fv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) add_to_carts FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) IS NOT NULL ) Fd ON Fb.ad_id = Fd.ad_id AND Fb.date_start = Fd.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) Add_to_cart_Value FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) IS NOT NULL ) Fdv ON Fb.ad_id = Fdv.ad_id AND Fb.date_start = Fdv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Landing_page_views FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) IS NOT NULL ) Fe ON Fb.ad_id = Fe.ad_id AND Fb.date_start = Fe.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Initiate_checkouts FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) IS NOT NULL ) Ff ON Fb.ad_id = Ff.ad_id AND Fb.date_start = Ff.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) Initiate_checkouts_Value FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) IS NOT NULL ) Ffv ON Fb.ad_id = Ffv.ad_id AND Fb.date_start = Ffv.date_start GROUP BY Adset_Name, Adset_ID, fb.ad_id, fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Fb.date_start; CREATE OR REPLACE TABLE maplemonk.zouk_FACEBOOK_CONSOLIDATED_overall AS WITH Facebook AS ( SELECT Adset_Name, Adset_ID, ad_id, ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, COALESCE(fsm.CATEGORY, fsm2.Category) AS CATEGORY, COALESCE(fsm.COLLECTION, fsm2.Collection) AS COLLECTION, SAFE_DIVIDE(IFNULL(reach,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) reach, SAFE_DIVIDE(IFNULL(frequency,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) frequency, SAFE_DIVIDE(IFNULL(Clicks,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Clicks, SAFE_DIVIDE(IFNULL(Link_Clicks,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Link_Clicks, SAFE_DIVIDE(IFNULL(Spend,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Spend, SAFE_DIVIDE(IFNULL(Impressions,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Impressions, SAFE_DIVIDE(IFNULL(Conversions,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Conversions, SAFE_DIVIDE(IFNULL(Meta_1D_Conversions,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Meta_1D_Conversions, SAFE_DIVIDE(IFNULL(Conversion_Value,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Conversion_Value, SAFE_DIVIDE(IFNULL(Meta_1D_Conversions_Value,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Meta_1D_Conversions_Value, SAFE_DIVIDE(IFNULL(Add_to_carts,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Add_to_carts, SAFE_DIVIDE(IFNULL(Add_to_cart_value,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Add_to_cart_value, SAFE_DIVIDE(IFNULL(purchase,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Purchase, SAFE_DIVIDE(IFNULL(video_views,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) video_views, SAFE_DIVIDE(IFNULL(Comment,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Comment, SAFE_DIVIDE(IFNULL(Post_Reaction,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Post_Reaction, SAFE_DIVIDE(IFNULL(Page_Engagement,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Page_Engagement, SAFE_DIVIDE(IFNULL(Facebook_Like,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Facebook_Like, SAFE_DIVIDE(IFNULL(Landing_page_views,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Landing_page_views, SAFE_DIVIDE(IFNULL(Initiate_checkouts,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Initiate_checkouts, SAFE_DIVIDE(IFNULL(Initiate_checkouts_value,0), COUNT(*) OVER(PARTITION BY date, ad_id, LOWER(IFNULL(ad_name,\'\')))) Initiate_checkouts_value FROM maplemonk.zouk_FACEBOOK_CONSOLIDATED_Intermediate mc LEFT JOIN ( SELECT * FROM ( SELECT CATEGORY, COLLECTION, ROW_NUMBER() OVER(PARTITION BY LOWER(CATEGORY), LOWER(COLLECTION) ORDER BY 1) rw FROM `MapleMonk.FINAL_SKU_MASTER` WHERE category IS NOT NULL AND category != \'\' ) WHERE rw = 1 ) fsm ON LOWER(REPLACE(IFNULL(mc.ad_name,\'\'),\'_\',\'&\')) LIKE \'%&\' || LOWER(fsm.category) || \'&%\' LEFT JOIN ( SELECT * FROM ( SELECT CATEGORY, COLLECTION, Category_Code, ROW_NUMBER() OVER(PARTITION BY LOWER(CATEGORY), LOWER(COLLECTION) ORDER BY 1) rw FROM `MapleMonk.FINAL_SKU_MASTER` WHERE category IS NOT NULL AND category != \'\' ) WHERE rw = 1 ) fsm2 ON LOWER(REPLACE(IFNULL(mc.ad_name,\'\'),\'_\',\'&\')) LIKE \'%&\' || LOWER(fsm2.category_code) || \'&%\' ), facebook_category AS ( SELECT Adset_Name, Adset_ID, mc.ad_id, mc.ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, fsm.CATEGORY, fsm.collection, SAFE_DIVIDE(IFNULL(reach,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) reach, SAFE_DIVIDE(IFNULL(frequency,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) frequency, SAFE_DIVIDE(IFNULL(Clicks,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Clicks, SAFE_DIVIDE(IFNULL(Link_Clicks,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Link_Clicks, SAFE_DIVIDE(IFNULL(Spend,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Spend, SAFE_DIVIDE(IFNULL(Impressions,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Impressions, SAFE_DIVIDE(IFNULL(Conversions,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Conversions, SAFE_DIVIDE(IFNULL(Meta_1D_Conversions,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Meta_1D_Conversions, SAFE_DIVIDE(IFNULL(Conversion_Value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Conversion_Value, SAFE_DIVIDE(IFNULL(Meta_1D_Conversions_Value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Meta_1D_Conversions_Value, SAFE_DIVIDE(IFNULL(Add_to_carts,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Add_to_carts, SAFE_DIVIDE(IFNULL(Add_to_cart_value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Add_to_cart_value, SAFE_DIVIDE(IFNULL(purchase,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Purchase, SAFE_DIVIDE(IFNULL(video_views,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) video_views, SAFE_DIVIDE(IFNULL(Comment,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Comment, SAFE_DIVIDE(IFNULL(Post_Reaction,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Post_Reaction, SAFE_DIVIDE(IFNULL(Page_Engagement,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Page_Engagement, SAFE_DIVIDE(IFNULL(Facebook_Like,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Facebook_Like, SAFE_DIVIDE(IFNULL(Landing_page_views,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Landing_page_views, SAFE_DIVIDE(IFNULL(Initiate_checkouts,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Initiate_checkouts, SAFE_DIVIDE(IFNULL(Initiate_checkouts_value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Initiate_checkouts_value FROM (SELECT * FROM facebook WHERE category IS NULL) mc LEFT JOIN ( SELECT * FROM ( SELECT REPLACE(CAST(ad_id AS STRING),\'`\',\'\') ad_id, AD_NAME, category, collection FROM maplemonk.zouk_meta WHERE category IS NOT NULL AND category != \'\' ) QUALIFY ROW_NUMBER() OVER(PARTITION BY LOWER(IFNULL(ad_id,\'\')), LOWER(IFNULL(AD_NAME,\'\')) ORDER BY 1) = 1 ) fsm ON LOWER(fsm.ad_id) = LOWER(mc.ad_id) AND LOWER(fsm.AD_NAME) = LOWER(mc.AD_NAME) ), facebook_collection AS ( SELECT Adset_Name, Adset_ID, mc.ad_id, mc.ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, fsm.CATEGORY, fsm.collection, SAFE_DIVIDE(IFNULL(reach,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) reach, SAFE_DIVIDE(IFNULL(frequency,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) frequency, SAFE_DIVIDE(IFNULL(Clicks,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Clicks, SAFE_DIVIDE(IFNULL(Link_Clicks,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Link_Clicks, SAFE_DIVIDE(IFNULL(Spend,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Spend, SAFE_DIVIDE(IFNULL(Impressions,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Impressions, SAFE_DIVIDE(IFNULL(Conversions,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Conversions, SAFE_DIVIDE(IFNULL(Meta_1D_Conversions,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Meta_1D_Conversions, SAFE_DIVIDE(IFNULL(Conversion_Value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Conversion_Value, SAFE_DIVIDE(IFNULL(Meta_1D_Conversions_Value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Meta_1D_Conversions_Value, SAFE_DIVIDE(IFNULL(Add_to_carts,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Add_to_carts, SAFE_DIVIDE(IFNULL(Add_to_cart_value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Add_to_cart_value, SAFE_DIVIDE(IFNULL(purchase,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Purchase, SAFE_DIVIDE(IFNULL(video_views,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) video_views, SAFE_DIVIDE(IFNULL(Comment,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Comment, SAFE_DIVIDE(IFNULL(Post_Reaction,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Post_Reaction, SAFE_DIVIDE(IFNULL(Page_Engagement,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Page_Engagement, SAFE_DIVIDE(IFNULL(Facebook_Like,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Facebook_Like, SAFE_DIVIDE(IFNULL(Landing_page_views,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Landing_page_views, SAFE_DIVIDE(IFNULL(Initiate_checkouts,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Initiate_checkouts, SAFE_DIVIDE(IFNULL(Initiate_checkouts_value,0), COUNT(*) OVER(PARTITION BY date, mc.ad_id, LOWER(IFNULL(mc.ad_name,\'\')))) Initiate_checkouts_value FROM (SELECT * FROM facebook_category WHERE category IS NULL) mc LEFT JOIN ( SELECT * FROM ( SELECT REPLACE(CAST(ad_id AS STRING),\'`\',\'\') ad_id, AD_NAME, category, collection FROM maplemonk.zouk_meta WHERE (category IS NULL OR category = \'\') AND collection IS NOT NULL AND collection != \'\' ) QUALIFY ROW_NUMBER() OVER(PARTITION BY LOWER(IFNULL(ad_id,\'\')), LOWER(IFNULL(AD_NAME,\'\')) ORDER BY 1) = 1 ) fsm ON LOWER(fsm.ad_id) = LOWER(mc.ad_id) AND LOWER(fsm.AD_NAME) = LOWER(mc.AD_NAME) ) SELECT * FROM facebook WHERE category IS NOT NULL UNION ALL SELECT * FROM facebook_category WHERE category IS NOT NULL UNION ALL SELECT * FROM facebook_collection; CREATE OR REPLACE TABLE maplemonk.zouk_DB_Product_FACEBOOK_CONSOLIDATED AS WITH SKU_Map AS ( SELECT DISTINCT Channel_Product_Id, SKU_Code, pm.Category_name, pm.Collection FROM `MapleMonk.new_zouk_db_get_product_listing` pl LEFT JOIN `MapleMonk.new_zouk_db_get_product_master` pm ON TRIM(LOWER(pl.sku_code)) = TRIM(LOWER(pm.Product_Code)) WHERE LOWER(pl.Channel_Code) LIKE \'shopify\' ) SELECT Adset_Name, Adset_ID, FB.ad_id, FB.ad_name, \'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' AS Account_Name, FB.Account_ID, Campaign_Name, Campaign_ID, CAST(Fb.date_start AS DATE) AS Date, SUM(CLICKS) AS Clicks, SUM(IFNULL(inline_link_clicks,0)) AS Link_Clicks, SUM(SPEND) AS Spend, SUM(IMPRESSIONS) AS Impressions, SUM(IFNULL(Fc.Conversions,0)) AS Conversions, SUM(IFNULL(Fc1.Conversions_1D_Click,0)) AS Meta_1D_Conversions, SUM(IFNULL(reach,0)) AS reach, SUM(IFNULL(frequency,0)) AS frequency, SUM(IFNULL(Fcv.Conversion_Value,0)) AS Conversion_Value, SUM(IFNULL(Fcv1.Conversion_Value_1D_Click,0)) AS Meta_1D_Conversions_Value, SUM(IFNULL(fd.add_to_carts,0)) AS Add_to_carts, SUM(IFNULL(fdv.add_to_cart_value,0)) AS Add_to_cart_value, SUM(IFNULL(fp.purchase,0)) AS Purchase, SUM(IFNULL(fv.video_views,0)) AS video_views, SUM(IFNULL(Fcm.Comment,0)) AS Comment, SUM(IFNULL(Frc.post_reaction,0)) AS Post_Reaction, SUM(IFNULL(Feg.page_engagement,0)) AS Page_Engagement, SUM(IFNULL(Fl.Facebook_Like,0)) AS Facebook_Like, SUM(IFNULL(fe.landing_page_views,0)) AS Landing_page_views, SUM(IFNULL(ff.initiate_checkouts,0)) AS Initiate_checkouts, SUM(IFNULL(ffv.initiate_checkouts_value,0)) AS Initiate_checkouts_value, \'Facebook\' AS Channel, \'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' AS Account, COALESCE(sm.category_name, fm.category) AS category, COALESCE(sm.collection, fm.collection) AS collection FROM ( SELECT * FROM `MapleMonk.zouk_db_product_customcampaigns_data` WHERE LOWER(IFNULL(ad_name,\'\')) LIKE \'%catalogue%\' ) FB LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') AS FLOAT64),0) + IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') AS FLOAT64),0)) Conversions FROM `maplemonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') IN (\'purchase\', \'offsite_conversion.fb_pixel_purchase\') GROUP BY ad_id, ad_name, date_start ) Fc ON Fb.ad_id = Fc.ad_id AND Fb.date_start = Fc.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.1d_click\') AS FLOAT64),0)) Conversions_1D_Click FROM `maplemonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') IN (\'purchase\') GROUP BY ad_id, ad_name, date_start ) Fc1 ON Fb.ad_id = Fc1.ad_id AND Fb.date_start = Fc1.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') AS FLOAT64),0) + IFNULL(CAST(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') AS FLOAT64),0)) Conversion_Value FROM `maplemonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(CV,\'$.action_type\') IN (\'purchase\', \'offsite_conversion.fb_pixel_purchase\') GROUP BY ad_id, ad_name, date_start ) Fcv ON Fb.ad_id = Fcv.ad_id AND Fb.date_start = Fcv.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64),0)) AS Conversion_Value_1D_Click FROM `maplemonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) AS C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'omni_purchase\' GROUP BY ad_id, ad_name, date_start ) Fcv1 ON Fb.ad_id = Fcv1.ad_id AND Fb.date_start = Fcv1.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64),0)) purchase FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'purchase\' GROUP BY 1,2 ) Fp ON FB.ad_id = Fp.ad_id AND FB.date_start = Fp.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) video_views FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'video_view\' GROUP BY 1,2 ) Fv ON FB.ad_id = Fv.ad_id AND FB.date_start = Fv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Comment FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'comment\' GROUP BY 1,2 ) Fcm ON FB.ad_id = Fcm.ad_id AND FB.date_start = Fcm.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Facebook_Like FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'like\' GROUP BY 1,2 ) Fl ON FB.ad_id = Fl.ad_id AND FB.date_start = Fl.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Page_Engagement FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'page_engagement\' GROUP BY 1,2 ) Feg ON FB.ad_id = Feg.ad_id AND FB.date_start = Feg.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Post_Reaction FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'post_reaction\' GROUP BY 1,2 ) Frc ON FB.ad_id = Frc.ad_id AND FB.date_start = Frc.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) add_to_carts FROM maplemonk.zouk_db_product_customcampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) IS NOT NULL ) Fd ON Fb.ad_id = Fd.ad_id AND Fb.date_start = Fd.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) Add_to_cart_Value FROM maplemonk.zouk_db_product_customcampaigns_data LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) IS NOT NULL ) Fdv ON Fb.ad_id = Fdv.ad_id AND Fb.date_start = Fdv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Landing_page_views FROM maplemonk.zouk_db_product_customcampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) IS NOT NULL ) Fe ON Fb.ad_id = Fe.ad_id AND Fb.date_start = Fe.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Initiate_checkouts FROM maplemonk.zouk_db_product_customcampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) IS NOT NULL ) Ff ON Fb.ad_id = Ff.ad_id AND Fb.date_start = Ff.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) Initiate_checkouts_Value FROM maplemonk.zouk_db_product_customcampaigns_data LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(JSON_EXTRACT_SCALAR(CV,\'$.value\') AS FLOAT64)) IS NOT NULL ) Ffv ON Fb.ad_id = Ffv.ad_id AND Fb.date_start = Ffv.date_start LEFT JOIN ( SELECT * FROM MapleMonk.FINAL_SKU_MASTER QUALIFY ROW_NUMBER() OVER(PARTITION BY LOWER(Channel_Product_Id) ORDER BY 1) = 1 ) Fm ON LOWER(TRIM(SPLIT(FB.product_id, \',\')[OFFSET(0)])) = LOWER(TRIM(SPLIT(Fm.Channel_Product_Id, \'-\')[OFFSET(ARRAY_LENGTH(SPLIT(Fm.Channel_Product_Id, \'-\')) - 1)])) LEFT JOIN ( SELECT * FROM SKU_Map QUALIFY ROW_NUMBER() OVER(PARTITION BY LOWER(Channel_Product_Id) ORDER BY 1) = 1 ) sm ON LOWER(TRIM(SPLIT(FB.product_id, \',\')[OFFSET(0)])) = LOWER(TRIM(SPLIT(sm.Channel_Product_Id, \'-\')[OFFSET(ARRAY_LENGTH(SPLIT(sm.Channel_Product_Id, \'-\')) - 1)])) GROUP BY Adset_Name, Adset_ID, FB.ad_id, FB.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID, FB.date_start, category, collection; CREATE OR REPLACE TABLE maplemonk.zouk_FACEBOOK_CONSOLIDATED AS SELECT Adset_Name, Adset_ID, ad_id, ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, CATEGORY, COLLECTION, reach, frequency, Clicks, Link_Clicks, Spend, Impressions, Conversions, Meta_1D_Conversions, Conversion_Value, Meta_1D_Conversions_Value, purchase, video_views, Comment, Post_Reaction, Page_Engagement, Facebook_Like, Add_to_carts, Add_to_cart_value, Landing_page_views, Initiate_checkouts, Initiate_checkouts_value FROM maplemonk.zouk_FACEBOOK_CONSOLIDATED_overall UNION ALL SELECT Adset_Name, Adset_ID, ad_id, ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, CATEGORY, COLLECTION, reach, frequency, Clicks, Link_Clicks, Spend, Impressions, Conversions, Meta_1D_Conversions, Conversion_Value, Meta_1D_Conversions_Value, purchase, video_views, Comment, Post_Reaction, Page_Engagement, Facebook_Like, Add_to_carts, Add_to_cart_value, Landing_page_views, Initiate_checkouts, Initiate_checkouts_value FROM maplemonk.zouk_DB_Product_FACEBOOK_CONSOLIDATED;",
                    "transaction": true
